// Set date variables in both English and Arabic
const now = new Date();

// Arabic month names
const arabicMonths = [
  'يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو',
  'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
];

// Arabic day names
const arabicDays = [
  'الأحد', 'الإثنين', 'الثلاثاء', 'الأربعاء', 'الخميس', 'الجمعة', 'السبت'
];

// Convert to Arabic numerals
function toArabicNumerals(num) {
  const arabicNumerals = ['٠', '١', '٢', '٣', '٤', '٥', '٦', '٧', '٨', '٩'];
  return num.toString().split('').map(d => arabicNumerals[parseInt(d)] || d).join('');
}

const day = now.getDate();
const month = now.getMonth();
const year = now.getFullYear();
const dayOfWeek = now.getDay();

const dateArabic = `${arabicDays[dayOfWeek]}، ${toArabicNumerals(day)} ${arabicMonths[month]} ${toArabicNumerals(year)}`;
const dateEnglish = now.toISOString().split('T')[0];
const fileName = `تقرير_يومي_${dateEnglish}.docx`;

return {
  json: {
    date_arabic: dateArabic,
    date_english: dateEnglish,
    year: year,
    month: month + 1,
    day: day,
    day_name_arabic: arabicDays[dayOfWeek],
    month_name_arabic: arabicMonths[month],
    file_name: fileName,
    report_title: `التقرير اليومي للرصد الجنائي والأمني - ${dateArabic}`,
    search_recency: 'day'
  }
};

// Merge all UAE news results from all inputs
const allItems = $input.all();
let allUaeNews = [];

// Collect news_results from all input items
for (const item of allItems) {
  const newsResults = item.json?.news_results || [];
  allUaeNews = [...allUaeNews, ...newsResults];
}

// Deduplicate by title
const seen = new Set();
const uniqueNews = allUaeNews.filter(news => {
  const key = news.title?.toLowerCase();
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

return {
  json: {
    uae_news_count: uniqueNews.length,
    uae_news: uniqueNews.slice(0, 15).map(n => ({
      title: n.title,
      source: n.source?.name || n.source,
      link: n.link,
      snippet: n.snippet,
      date: n.date
    }))
  }
};

// Merge GCC news results from all inputs
const allItems = $input.all();
let allGccNews = [];

// Collect news_results from all input items
for (const item of allItems) {
  const newsResults = item.json?.news_results || [];
  allGccNews = [...allGccNews, ...newsResults];
}

// Deduplicate
const seen = new Set();
const uniqueNews = allGccNews.filter(news => {
  const key = news.title?.toLowerCase();
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

return {
  json: {
    gcc_news_count: uniqueNews.length,
    gcc_news: uniqueNews.slice(0, 15).map(n => ({
      title: n.title,
      source: n.source?.name || n.source,
      link: n.link,
      snippet: n.snippet,
      date: n.date
    }))
  }
};

// Merge international news results from all inputs
const allItems = $input.all();
let allNews = [];

// Collect all news_results from inputs
for (const item of allItems) {
  const newsResults = item.json?.news_results || [];
  allNews = [...allNews, ...newsResults];
}

// Split into categories (first third international, second third european, last third american)
const third = Math.ceil(allNews.length / 3);

return {
  json: {
    international_news: allNews.slice(0, 10).map(n => ({
      title: n.title,
      source: n.source?.name || n.source,
      link: n.link,
      snippet: n.snippet,
      date: n.date
    })),
    european_news: allNews.slice(third, third + 10).map(n => ({
      title: n.title,
      source: n.source?.name || n.source,
      link: n.link,
      snippet: n.snippet,
      date: n.date
    })),
    american_news: allNews.slice(third * 2, (third * 2) + 10).map(n => ({
      title: n.title,
      source: n.source?.name || n.source,
      link: n.link,
      snippet: n.snippet,
      date: n.date
    }))
  }
};

// Merge international organization updates from parallel inputs
const allItems = $input.all();

// Collect all organic results from parallel SERP API calls
let allOrgUpdates = [];
for (const item of allItems) {
  const results = item.json?.organic_results || [];
  for (const r of results.slice(0, 5)) {
    allOrgUpdates.push({
      title: r.title,
      link: r.link,
      snippet: r.snippet
    });
  }
}

// Distribute updates across organization categories
const perCategory = 5;
return {
  json: {
    unodc_updates: allOrgUpdates.slice(0, perCategory),
    interpol_updates: allOrgUpdates.slice(perCategory, perCategory * 2),
    europol_updates: allOrgUpdates.slice(perCategory * 2, perCategory * 3),
    fbi_updates: allOrgUpdates.slice(perCategory * 3, perCategory * 4),
    all_org_updates: allOrgUpdates
  }
};

