// Collect references from Perplexity citations
const inputData = $json;
const citations = inputData.citations || [];

const references = [];

// Process Perplexity citations
citations.forEach((cite, index) => {
  if (cite) {
    references.push({
      title: `Reference ${index + 1}`,
      url: cite,
      source_type: 'news',
      source_name: 'Perplexity AI',
      publication_date: new Date().toISOString().split('T')[0],
      crime_type: ['other'],
      region: ['Global'],
      geographical_scope: 'international'
    });
  }
});

return {
  json: {
    operation: 'ADD_BATCH_REFERENCES',
    references: references.slice(0, 50)
  }
};

// Generate the complete Arabic report
const allInputs = $input.all();

// Get current date for report
const now = new Date();
const dateArabic = now.toLocaleDateString('ar-AE', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
const dateEnglish = now.toISOString().split('T')[0];
const fileName = `criminal_daily_report_${dateEnglish}.html`;
const reportTitle = `التقرير اليومي للرصد الجنائي - ${dateArabic}`;

// Extract analyses from inputs
let analyses = [];
let allCitations = [];
for (const input of allInputs) {
  const content = input.json?.choices?.[0]?.message?.content;
  if (content) analyses.push(content);
  const citations = input.json?.citations || [];
  allCitations = [...allCitations, ...citations];
}

// Build sections from available analyses
const executiveSummary = analyses[0] || 'لا تتوفر بيانات';
const patternAnalysis = analyses[1] || 'لا تتوفر بيانات';

// Format references
const uniqueCitations = [...new Set(allCitations)];
let referencesSection = '';
uniqueCitations.forEach((cite, i) => {
  referencesSection += `${i + 1}. ${cite}\n`;
});
if (!referencesSection) referencesSection = 'المراجع متوفرة في نظام قاعدة البيانات المرجعية';

const report = `
═══════════════════════════════════════════════════════════════
التقرير اليومي للرصد الجنائي والأمني
───────────────────────────────────────────────────────────────
التاريخ: ${dateArabic}
وقت الإصدار: ٠٧:٠٠ صباحاً بتوقيت الإمارات
═══════════════════════════════════════════════════════════════

═══════════════════════════════════════════════════════════════
١. الملخص التنفيذي
═══════════════════════════════════════════════════════════════
${executiveSummary}

═══════════════════════════════════════════════════════════════
٢. تحليل الأنماط الجنائية
═══════════════════════════════════════════════════════════════
${patternAnalysis}

═══════════════════════════════════════════════════════════════
٣. المراجع والمصادر
═══════════════════════════════════════════════════════════════
${referencesSection}

───────────────────────────────────────────────────────────────
نهاية التقرير
تم إعداد هذا التقرير آلياً بواسطة نظام الرصد الجنائي
───────────────────────────────────────────────────────────────
`;

return {
  json: {
    report_content: report,
    report_title: reportTitle,
    file_name: fileName,
    date: dateEnglish
  }
};

// Create Word document content
const reportData = $input.first().json;

// Convert report to base64 for binary handling
